mapper.select:
select  
a.plant_cd = #{plantCd}
order by a.plant_cd, a.asrs_cd

mapper.update:
update wms_asrs
   set asrs_nm = #{f.asrsNm}, in_node_id = #{f.inNodeId}, out_node_id = #{f.outNodeId}, terminal_id = #{f.terminalId},
       conn_mode = #{f.connMode}, wes_url = #{f.wesUrl}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where asrs_id = #{id} and row_ver = #{f.rowVer}

update wms_ctr_type
   set type_nm = #{f.typeNm}, length_mm = #{f.lengthMm}, width_mm = #{f.widthMm}, height_mm = #{f.heightMm}, slot_cnt = #{f.slotCnt},
       use_yn = #{f.useYn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where type_id = #{id} and row_ver = #{f.rowVer}

mapper.select:
select  

    and c.asrs_id = #{asrsId}
    and c.status = #{status}
    and c.ctr_cd like #{like} escape '\'

order by c.ctr_cd
limit 500

select  

    and r.asrs_id = #{asrsId}
    and r.send_state = #{sendState}

order by r.req_id desc
limit #{limit}

select r.req_id, r.asrs_id, r.req_type, r.req_key, r.send_state, r.row_ver, r.urgent_yn, r.urgent_reason from wms_asrs_req r
 where r.asrs_id = #{asrsId} and r.req_key = #{reqKey}
   for update

mapper.update:
update wms_asrs_req
   set send_state = #{state}, outbox_message_id = coalesce(#{messageId}, outbox_message_id),
       sent_at = case when #{state}::varchar = 'SENT' then coalesce(sent_at, now()) else sent_at end,
       claimed_at = case when #{state}::varchar = 'SENT' and #{messageId}::uuid is null then now() else claimed_at end,
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where req_id = #{id}

update wms_asrs_req_line
   set status = #{status}, wes_status = #{wesStatus}, done_qty = coalesce(#{doneQty}, done_qty), last_reason = #{reason},
       started_at = case when #{status}::varchar <> 'NOT_STARTED' then coalesce(started_at, now()) else started_at end,
       finished_at = case when #{status}::varchar in ('DONE', 'FAILED', 'CANCELLED', 'SHORT') then coalesce(finished_at, now()) end,
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where line_id = #{lineId}

mapper.select:
select req_id from wms_asrs_req where asrs_id = #{asrsId} and send_state = 'QUEUED'
 order by req_id limit #{max}
   for update skip locked

select r.recon_id, r.asrs_id, r.snap_key, r.status, r.part_cnt, r.expected_parts from wms_asrs_recon r
 where r.asrs_id = #{asrsId} and r.snap_key = #{snapKey}
   for update

select  from wms_asrs_recon r join wms_asrs a on a.asrs_id = r.asrs_id
r.asrs_id = #{asrsId}
 order by r.recon_id desc limit #{limit}
